UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification reflects the role of individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts.</p> <p>Individuals at this level display initiative and judgement in planning, organising, implementing, and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p> <p>They may plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse, and synthesise information from a variety of sources.<br/> The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a href="https://training.gov.au/Training/Details/BSB50420">https://training.gov.au/Training/Details/BSB50420</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/bsb50420-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '110097D';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p> <p>Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p> <p>They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p> <p>The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a href="https://training.gov.au/Training/Details/BSB60420">https://training.gov.au/Training/Details/BSB60420</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/bsb60420-advanced-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '110098C';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. </span></p> <p><span style="font-weight: 400;">Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</span></p> <p><span style="font-weight: 400;">This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director.</span></p> <p><span style="font-weight: 400;">The latest release of the qualification and packaging rules can be found at the following link:</span></p> <p><a href="https://training.gov.au/Training/Details/BSB80120"><span style="font-weight: 400;">https://training.gov.au/Training/Details/BSB80120</span></a><span style="font-weight: 400;"> </span></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/bsb80120-graduate-diploma-of-management-learning/',
    updated_at = NOW()
WHERE cricos_course_code = '110099B';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification reflects the role of individuals in the community, home or residential care setting who work under supervision and delegation as a part of a multi-disciplinary team, following an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason.</p> <p> These individuals take responsibility for their own outputs within the scope of their job role and delegation. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p> <p> The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p> <p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p> <p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <p><a href="https://training.gov.au/training/details/CHC33021">https://training.gov.au/training/details/CHC33021</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/chc33021-certificate-iii-in-individual-support/',
    updated_at = NOW()
WHERE cricos_course_code = '117674H';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification reflects the role of individuals in a range of community settings and peoples’ homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.</p> <p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p> <p>No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <p><a href="https://training.gov.au/training/details/CHC43121">https://training.gov.au/training/details/CHC43121</a></p> <p></p>',
