UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</span></p> <p><span style="font-weight: 400;">At this level, workers have specialised skills in community services and work autonomously within their scope of practice under broad directions from senior management.</span></p> <p><span style="font-weight: 400;">Workers support people to make change in their lives to improve personal and social wellbeing and may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</span></p> <p><span style="font-weight: 400;">To achieve this qualification, the candidate must have completed at least 200 hours of work as detailed in the Assessment Requirements of units of competency. (Radix Education has schedule 220 hours of work placement; please refer to the detailed training and assessment schedule)</span></p> <p><span style="font-weight: 400;">The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</span></p> <p><span style="font-weight: 400;">No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</span></p> <p><a href="https://training.gov.au/training/details/CHC52025">https://training.gov.au/training/details/CHC52025</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/chc52025-diploma-of-community-services/',
    updated_at = NOW()
WHERE cricos_course_code = '118791F';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This is a trade qualification for carpenters in residential and commercial workplaces. It includes setting out, manufacturing, constructing, assembling, installing and repairing products made using timber and non-timber materials.</span></p> <p><span style="font-weight: 400;">Occupational titles may include:</span></p> <p><span style="font-weight: 400;">State and territory jurisdictions may have different licensing, legislative, regulatory or certification requirements. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.</span></p> <p><span style="font-weight: 400;">Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</span></p> <p><span style="font-weight: 400;">This qualification is suitable for an Australian apprenticeship pathway.</span></p> <p><a href="https://training.gov.au/training/details/CPC30220">https://training.gov.au/training/details/CPC30220</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/cpc30220-certificate-iii-in-carpentry/',
    updated_at = NOW()
WHERE cricos_course_code = '110897E';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification provides a trade outcome in painting and decorating for residential and commercial construction work.</p> <p>Occupational titles may include:</p> <p>Licensing, legislative and regulatory or certification requirements for painting and decorating work differ between States and Territories.</p> <p>Please consult with the relevant regulatory authority. This qualification is suitable for an Australian Apprenticeship pathway.</p> <p>Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</p> <p><a href="https://training.gov.au/training/details/CPC30620">https://training.gov.au/training/details/CPC30620</a></p> <p></p>',
