UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the trade qualified role of a bricklayer, block layer or paver who may have responsibility for undertaking heritage bricklaying, refractory bricklaying, bricklaying, block laying and paving work in residential, industrial and commercial contexts, in both existing and new constructions. Occupational titles could include:</span></p> <p><span style="font-weight: 400;">The bricklaying, block laying and paving industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or closely simulated workplace environment and this qualification requires all units of competency to be delivered and assessed in this context.</span></p> <p><span style="font-weight: 400;">Licensing, legislative, regulatory and certification requirements vary between states. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.</span></p> <p><span style="font-weight: 400;">Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</span></p> <p><a href="https://training.gov.au/training/details/CPC33020">https://training.gov.au/training/details/CPC33020</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
