    apply_form = 'https://ciet.edu.au/course/cpc33020-certificate-iii-in-bricklaying-and-blocklaying/',
    updated_at = NOW()
WHERE cricos_course_code = '110898D';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of builders, site managers and managers of small to medium-sized building businesses who apply knowledge of structural principles, codes, standards and legal requirements to Class 1 and 10, to a maximum of two storeys and Class 2 to 9 Type C constructions, and who plan and supervise safe building and construction work, prepare and administer contracts, and who apply quality principles to building and construction projects.</span></p> <p><span style="font-weight: 400;">Building relates to construction and Site Management is about managing the factors around construction, such as the deployment of crews with specialised skills (including builders), product compliance, deployment of contract specialised skills, weather and site location.</span></p> <p><span style="font-weight: 400;">Occupational titles depending on packaging options selected may include:</span></p> <p><span style="font-weight: 400;">The qualification is designed to enable two specialised occupational outcome pathways depending on elective options which will be reflected as:</span></p> <p><span style="font-weight: 400;">Completion of the general construction induction training program specified by the model Code of Practice for Construction Work is required for any person who is to carry out construction work. Achievement of unit CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</span></p> <p><span style="font-weight: 400;">Builder and Site Supervisor licensing varies across States and Territories and requirements additional to the attainment of this qualification may be required.</span></p> <p>The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a draggable="false" href="https://training.gov.au/Training/Details/CPC40120" rel="noopener" target="_blank">https://training.gov.au/Training/Details/CPC40120</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/cpc40120-cert-iv-in-building-construction/',
    updated_at = NOW()
WHERE cricos_course_code = '110100C';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of building professionals who apply knowledge of structural principles, risk, and financial management, estimating, preparing, and administering building and construction contracts, selecting contractors, overseeing the work and its quality, and managing construction work in building projects including residential and commercial with the following limitations:</span></p> <p><span style="font-weight: 400;">Occupational titles may include:</span></p> <p><span style="font-weight: 400;">The construction industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or very closely simulated workplace environment. To achieve this qualification, the candidate must have access to a live building and construction workplace to meet the requirements detailed in the Assessment Requirements of core unit CPCCBC4008 Supervise communication and administration processes for building and construction projects.</span></p> <p><span style="font-weight: 400;">Completion of the general construction induction training program specified by the model Code of Practice for Construction Work is required for any person who is to carry out construction work. Achievement of unit CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</span></p> <p><span style="font-weight: 400;">Builder licensing varies across States and Territories and requirements additional to the attainment of this qualification may be required.</span></p> <p><span style="font-weight: 400;">The latest release of the qualification and packaging rules can be found at the following link:</span></p> <p><a href="https://training.gov.au/Training/Details/CPC50220"><span style="font-weight: 400;">https://training.gov.au/Training/Details/CPC50220</span></a><span style="font-weight: 400;"> </span></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/cpc50220-diploma-of-building-and-construction-building/',
    updated_at = NOW()
WHERE cricos_course_code = '110101B';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification is designed to meet the needs of builders or senior managers within the building and construction industry who apply knowledge of building, construction and sustainability systems and processes, structural principles, codes, standards and legal obligations to construction projects including high rise.</span></p> <p><span style="font-weight: 400;">Occupational titles may include:</span></p> <p><span style="font-weight: 400;">The construction industry strongly affirms that training and assessment leading to recognition of skills must be undertaken in a real or very closely simulated workplace environment and this qualification requires all included units of competency to be delivered in this context.</span></p> <p><span style="font-weight: 400;">Completion of the general construction induction training program specified by the model Code of Practice for Construction Work is required for any person who is to carry out construction work. Achievement of unit CPCCWHS1001 Prepare to work safely in the construction industry meets this requirement.</span></p> <p><span style="font-weight: 400;">Builder licensing varies across States and Territories and requirements additional to the attainment of this qualification may be required. Additional or prescribed units of competency may also be required to meet builder registration requirements in various States and Territories.</span></p> <p>The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a href="https://training.gov.au/Training/Details/CPC60220">https://training.gov.au/Training/Details/CPC60220</a> </p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/cpc60220-adv-diploma-of-building-construction/',
    updated_at = NOW()
WHERE cricos_course_code = '104882G';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>CIET offers a White Card course that combines face-to-face, a self-paced learning and assessment programme. National code-compliant safety training for workers in the ACT and NSW construction industry. (CPCWHS1001 Work safely in the construction industry). All persons on a construction site must complete WHS Induction training and obtain the General Construction Induction (White Card Training) before they are permitted on a building site.</p> <p>There are no prerequisites for this course. You also need to have Personal Protective Equipment (PPE) including a hard hat, high vest, ear protection, and eye protection. If you don’t have PPE, you can get it from CIET staff once you’ve enrolled and paid for the course. Please email at admin@ciet.edu.au to find out where and when you can pick up your PPE. </p> <p>Please feel free to contact CIET by email: admin@ciet.edu.au to complete the details required prior to enrolling in the course.</p> <p>Payment can be made in person at CIET Student Services at Ground Floor 15 Barry Drive, Turner ACT 2612. Payment must be made prior to the course start date.</p> <p>Parking- Free parking is available at the back of the college building.</p> <p>Timings- 9:00 am to 3.30 pm </p> <p>Students that satisfactorily complete the competency will be eligible to apply for the National Construction Induction Card. You have 60 days from the issue of the transcript to apply for your card. Applications are made online via the Access Canberra Website. The cost will be $100 and is payable</p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/cpcwhs1001-white-card/',
    updated_at = NOW()
WHERE cricos_course_code = 'A';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This first aid course teaches the skills and knowledge needed to recognize emergencies and provide immediate and effective first aid to anyone suffering from a sudden illness or injury, in accordance with the legal, workplace, and community considerations, as well as the guidelines of the Australian Resuscitation Council and other national peak clinical bodies in Australia.</p> <p>Assessing the casualty, providing safety, contacting emergency services, and using resources to provide first aid, such as CPR and the use of a defibrillator, administering an autoinjector for anaphylaxis, administering asthma medication, assisting someone who is choking, using appropriate immobilization techniques for envenomation, fractures, dislocations, sprains and strains, and managing casualties with non-life-threatening bleeding and shock. The importance of the survival chain, written and verbal reporting of event information, reviewing occurrences to enhance personal abilities and response times, recognizing psychological effects, and seeking help as required will be discussed during the study period.</p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/hltaid0011-provide-first-aid/',
    updated_at = NOW()
WHERE cricos_course_code = 'A';

