UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of individuals in a variety of information and communications technology (ICT) roles who have significant experience in specialist technical skills, or managerial business and people management skills.</span></p> <p><span style="font-weight: 400;">Individuals in these roles carry out complex tasks in a specialist field, working independently, leading a team or a strategic direction of a business. They apply their skills across a wide range of industries and business functions, or as a business owner (sole trader/contractor). </span></p> <p><span style="font-weight: 400;">The skills required for these roles may include, but are not restricted to:</span></p> <p><span style="font-weight: 400;">No licensing, legislative or certification apply to this qualification at the time of publication.</span></p> <p>The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a href="https://training.gov.au/training/details/ICT60220">https://training.gov.au/training/details/ICT60220</a> </p> <p></p>',
