UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p><span style="font-weight: 400;">This qualification reflects the role of cooks who use a wide range of well-developed cookery skills and sound knowledge of kitchen operations to prepare food and menu items. Using discretion and judgement, they work with some independence and under limited supervision using plans, policies and procedures to guide work activities.</span></p> <p><span style="font-weight: 400;">Completion of this qualification contributes to recognition as a trade cook.</span></p> <p><span style="font-weight: 400;">This qualification provides a pathway to work as a cook in organisations such as restaurants, hotels, clubs, pubs, cafes, and coffee shops.</span></p> <p><span style="font-weight: 400;">The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.</span></p> <p>The latest release of the qualification and packaging rules can be found at the following link:</p> <p><a href="https://training.gov.au/training/details/SIT30821">https://training.gov.au/training/details/SIT30821</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
