UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>This qualification reflects the role of commercial cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.<br/> This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.</p> <p> The latest release of the qualification and packaging rules can be found at the following link:<br/> <a href="https://training.gov.au/training/details/SIT40521">https://training.gov.au/training/details/SIT40521</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="kt-accordion-panel-inner"> <p>Canberra Institute of Education and Technology has the following entry requirements:</p> <p>You must:</p> <ul> <li aria-level="1">be at least 18 years of age.</li> <li aria-level="1">participate in a course entry interview to determine suitability for the course and student needs. The course entry interview will also assess whether students can use digital technologies.</li> <li aria-level="1">have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 4 for reading, writing, numeracy and oral communication to enter the course.</li> <li aria-level="1">have an IELTS* score of 6.0 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following: <ul style="list-style-type: circle;"> <li aria-level="1">educated for 5 years in an English-speaking country; or</li> <li aria-level="1">successful completion of an English Placement Test at IELTS level 6.0.</li> </ul> </li> </ul> <p>*Note that other English language tests such as PTE and TOEFL can be accepted. Students are required to provide their results so that it can be confirmed they are equivalent to IELTS 6.0.</p> <p>Domestic students must have sufficient language, literacy and numeracy skills as tested through a language, literacy and numeracy assessment. Students will need to achieve ACSF level 3 for reading, writing, numeracy and oral communication to enter the course.</p> </div>',
    apply_form = 'https://ciet.edu.au/course/sit40516-certificate-iv-in-commercial-cookery-2/',
