    apply_form = 'https://ciet.edu.au/course/sit50416-diploma-of-hospitality-management/',
    updated_at = NOW()
WHERE cricos_course_code = '110895G';

UPDATE courses SET
    course_description = '<p class="kt-adv-heading_3dcf2b-33 wp-block-kadence-advancedheading" data-kb-block="kb-adv-heading_3dcf2b-33"> </p> <p>The Advanced Diploma of Hospitality Management qualification provides the skills and knowledge for a student to be competent as a senior manager in any hospitality functional area (except kitchen). This individual would analyse, design and execute judgements using wide-ranging technical, creative, conceptual or managerial competencies. Their knowledge base may be specialised or broad and they are often accountable for group outcomes. Work would be undertaken in various hospitality settings, such as restaurants, hotels, catering operations, motels, clubs, pubs, cafes and coffee shops.</p> <p>Subject areas include all subjects at Diploma level and additional subjects such as:</p> <p><a href="https://training.gov.au/training/details/SIT60322">https://training.gov.au/training/details/SIT60322</a></p> <p></p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
